do $release$ declare payload jsonb:='{"batch":"nl-scale-20261102-026","project":"qvplwejffhjvxaypmjut","actions":[{"ref":"d0","relation":"catalog_work_descriptions","key":{"work_id":6319,"language":"nl"},"before":null,"after":{"work_id":6319,"language":"nl","bound_author_id":3391,"text":"Advocaat Victor Carl probeert een nieuw proces te krijgen voor een man die voor de moord op zijn vrouw is veroordeeld. Hij komt daarbij niet alleen tegenover politie en aanklager te staan, maar krijgt ook te maken met Bob, een opvallend behulpzame bemoeial. Dankzij hem lijkt Victors eigen leven op verschillende punten beter te worden. Wanneer er een verband blijkt tussen Bob en de vermoorde vrouw, wordt die hulp minder geruststellend. De zaak dwingt Victor opnieuw te beoordelen wat achter de goede bedoelingen van anderen kan schuilgaan.","source_type":"official_catalog","source_name":"Gecontroleerde boek- en catalogusbronnen","source_url":"https://www.bol.com/nl/nl/p/de-verliezers/1001004002605001/","evidence":[{"type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p297930710"],"checked_at":"2026-11-02T22:27:17.469Z","reference":"work:6319","note":"ExactDutchA.W.Bruna2007paperback9789022991411/FallsTheShadow2005 with translatorJanSmit. FrontWilliamLashner/Deverliezers matches exact source; do not substitute anotherVictorCarlbook or confuse publicationyear2005original with2007translation.","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-034.json","sources":["https://www.bol.com/nl/nl/p/de-verliezers/1001004002605001/","https://knihobot.cz/g/9701014","https://openlibrary.org/works/OL2952400W","https://data.bibliotheken.nl/id/nbt/p297930710"]},{"type":"cover_front_review","cover_id":13010512,"sha256":"f53d979e01d6501ec2d606f8728de437e957e4dff5011af3eeb73e0d09bf48e3","reference":"cover-semantic-review-011.json","limitation":"William Lashner; De verliezers; classical colonnade and eye; thriller h